package com.booklibrary.stacks;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.Set;

/**
 * The OpenAPI spec generated by book-api, plus the API Gateway extensions it needs.
 *
 * <p>Only adds to or trims the spec. Paths, parameters, schemas and responses stay exactly as the
 * Spring code produced them. Plain JSON editing, no CDK involved.
 */
final class ApiGatewaySpec {

  private static final ObjectMapper MAPPER = new ObjectMapper();

  private static final Set<String> HTTP_METHODS =
      Set.of("get", "put", "post", "delete", "patch", "head", "options");

  private static final String VALIDATE_BODY_AND_PARAMS = "body-and-params";
  private static final String VALIDATE_PARAMS_ONLY = "params-only";

  private final ObjectNode root;
  private final Path source;

  private ApiGatewaySpec(ObjectNode root, Path source) {
    this.root = root;
    this.source = source;
  }

  /**
   * Reads the spec written by OpenApiSpecGeneratorTest during {@code `mvn package`} in book-api.
   *
   * @param file
   * @return
   */
  static ApiGatewaySpec load(Path file) {
    if (!Files.exists(file)) {
      throw new IllegalStateException(
          "OpenAPI spec not found at "
              + file.toAbsolutePath().normalize()
              + ". Build book-api first with `mvn clean package` (without -DskipTests: the spec"
              + " is generated by a test).");
    }
    try {
      return new ApiGatewaySpec((ObjectNode) MAPPER.readTree(file.toFile()), file);
    } catch (IOException e) {
      throw new IllegalStateException("Could not read OpenAPI spec at " + file, e);
    }
  }

  /**
   * springdoc records the local server (http://localhost). API Gateway sets its own.
   *
   * @return {@link ApiGatewaySpec}
   */
  ApiGatewaySpec withoutServers() {
    root.remove("servers");
    return this;
  }

  ApiGatewaySpec withInfo(String title, String description) {
    ObjectNode info = root.withObject("/info");
    info.put("title", title);
    info.put("description", description);
    return this;
  }

  /**
   * Adds the validators API Gateway runs before calling Lambda. Failures return 400 without
   * invoking Lambda.
   *
   * @return {@link ApiGatewaySpec}
   */
  ApiGatewaySpec withRequestValidators() {
    ObjectNode validators = root.putObject("x-amazon-apigateway-request-validators");
    validators
        .putObject(VALIDATE_BODY_AND_PARAMS)
        .put("validateRequestBody", true)
        .put("validateRequestParameters", true);
    validators
        .putObject(VALIDATE_PARAMS_ONLY)
        .put("validateRequestBody", false)
        .put("validateRequestParameters", true);
    return this;
  }

  /**
   * Points every operation at the Lambda (proxy integration) and assigns it a request validator.
   *
   * @param lambdaInvocationUri API Gateway URI for invoking the function
   */
  ApiGatewaySpec withLambdaIntegration(String lambdaInvocationUri) {
    JsonNode paths = root.path("paths");
    if (!paths.isObject() || paths.isEmpty()) {
      throw new IllegalStateException("OpenAPI spec at " + source + " has no paths.");
    }

    // httpMethod is always POST when API Gateway invokes Lambda, whatever the client's method was.
    ObjectNode integration = MAPPER.createObjectNode();
    integration.put("type", "aws_proxy");
    integration.put("httpMethod", "POST");
    integration.put("uri", lambdaInvocationUri);
    integration.put("passthroughBehavior", "when_no_match");

    paths.forEach(
        pathItem ->
            pathItem
                .fields()
                .forEachRemaining(
                    entry -> {
                      // Skip path-level entries such as "parameters".
                      if (HTTP_METHODS.contains(entry.getKey())) {
                        ObjectNode operation = (ObjectNode) entry.getValue();
                        operation.set("x-amazon-apigateway-integration", integration.deepCopy());
                        operation.put(
                            "x-amazon-apigateway-request-validator", validatorFor(entry.getKey()));
                      }
                    }));
    return this;
  }

  /**
   * Bodies are validated on POST only
   *
   * @param httpMethod {@link String}
   * @return {@link String}
   */
  private static String validatorFor(String httpMethod) {
    return "post".equals(httpMethod) ? VALIDATE_BODY_AND_PARAMS : VALIDATE_PARAMS_ONLY;
  }

  /**
   * The spec as nested maps, in the key order of the source file, for CDK to embed
   *
   * @return {@link Map}
   */
  Map<String, Object> toMap() {
    return MAPPER.convertValue(root, new TypeReference<>() {});
  }
}
